#!/usr/bin/env node
// Generates the manual-testing fixtures for the spreadsheet-import field
// guide. The shapes are dictated by docs/specs/0008-spreadsheet-import.md,
// section "The fixture" — one small workbook per journey that needs a shape
// a single CSV cannot have, plus the CSVs the journeys still ride.
//
//   node docs/manual/fixtures/make-fixtures.mjs          (from the repo root)
//   pnpm manual:fixtures
//
// It also writes manifest.json, which docs/manual is built from: the manual's
// fixture catalog is generated by joining that manifest against the files
// actually on disk, so a fixture that is described but not emitted (or
// emitted but not described) fails the manual build rather than shipping a
// dead download link.
//
// Every fixture here is deliberately BENIGN — the spec says so. Hostile input
// (leading-zero codes, 16-digit identifiers, 70-character headers) belongs to
// the rules' properties and boundaries, never to a fixture.
import { createRequire } from 'node:module'
import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url)) // docs/manual/fixtures
const ROOT = process.argv[2] ?? join(HERE, '../../..')
const require = createRequire(join(ROOT, 'apps/web/package.json'))
const XLSX = require('xlsx')

const out = HERE
mkdirSync(out, { recursive: true })

/** Manifest rows, in catalog order. */
const manifest = []
const csv = (file, rows, entry) => {
  writeFileSync(join(out, file), rows.join('\n') + '\n')
  manifest.push({ file, ...entry })
}

/**
 * Write a workbook. `sheets` is [name, rows, hidden?] where hidden is
 * 0 ordinary · 1 hidden · 2 very hidden (the state only VBA can set).
 * The zip's mtimes are pinned so re-running leaves the tree clean.
 */
const FIXED_DATE = new Date(Date.UTC(2026, 0, 1, 0, 0, 0))
const workbook = (file, sheets, entry) => {
  const wb = XLSX.utils.book_new()
  for (const [name, rows] of sheets) {
    XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(rows), name)
  }
  wb.Workbook = { Sheets: sheets.map(([name, , hidden]) => ({ name, Hidden: hidden ?? 0 })) }
  wb.Props = { CreatedDate: FIXED_DATE, ModifiedDate: FIXED_DATE }
  XLSX.writeFile(wb, join(out, file))
  manifest.push({
    file,
    sheets: sheets.map(([name, rows, hidden]) => ({
      name,
      rows: rows.length - 1,
      headers: rows[0].map(String),
      visibility: hidden === 2 ? 'very hidden' : hidden === 1 ? 'hidden' : 'visible',
    })),
    ...entry,
  })
}

/* ------------------------------------------------------------------ *
 * The agreement instrument — zones.csv. J1 and J2 ride it.
 * Eight rows, six columns, each column landing on a different inferred
 * type without a judgement call.
 * ------------------------------------------------------------------ */
csv(
  'zones.csv',
  [
    'Zone Name,Region,Population,Area Sq Km,Opened On,Is Active',
    'Alpha,North,12000,45.5,2026-01-15,yes',
    'Bravo,South,8400,12.25,2026-01-16,no',
    'Charlie,North,23100,88.0,2026-01-17,yes',
    'Delta,South,5600,7.75,2026-01-18,no',
    'Echo,North,15800,52.1,2026-02-02,yes',
    'Foxtrot,South,9900,31.4,2026-02-10,yes',
    'Golf,North,4300,6.8,2026-03-01,no',
    'Hotel,South,18700,64.9,2026-03-15,yes',
  ],
  {
    journeys: ['IMP-J1', 'IMP-J2'],
    shape: '8 rows · 6 columns',
    provokes:
      'The agreement instrument. Every column lands on a different inferred type with no judgement call: Choice (North/South), Int, Float, Date, Check.',
  },
)

/* ---- zones-updates.csv — J2's upsert branch, owned by spec 0004 ---- */
csv(
  'zones-updates.csv',
  [
    'Zone Name,Region,Population,Area Sq Km,Opened On,Is Active',
    'Alpha,North,12500,45.5,2026-01-15,yes',
    'Delta,South,,7.75,2026-01-18,yes',
    'Hotel,South,19200,64.9,2026-03-15,no',
    'India,North,7700,21.0,2026-04-01,yes',
    'Juliet,South,3100,4.2,2026-04-09,no',
    'Alpha,North,99999,45.5,2026-01-15,yes',
  ],
  {
    journeys: ['IMP-J2'],
    shape: '6 rows against Zones',
    provokes:
      'The matched-key half of J2, which spec 0004 owns: 3 updates, 2 inserts, one blank cell (Delta’s Population — keep or clear) and one key duplicated inside the file (Alpha twice).',
  },
)

/* ---- zones-messy.csv — J1.6's bad-cell branch, and J5.6 / J5.7 ---- */
csv(
  'zones-messy.csv',
  [
    'Zone Name,Region,Population,Area Sq Km,Opened On,Is Active',
    'Kilo,North,11200,33.3,2026-05-01,yes',
    'Lima,South,twelve thousand,9.9,2026-05-02,no',
    'Mike,North,8100,14.6,not a date,yes',
    ',,,,,',
    'November,South,6600,11.1,2026-05-04,no',
    'Oscar,North,-50,2.2,2026-05-05,maybe',
    'Papa,South,7200,18.8,2026-05-06,yes',
  ],
  {
    journeys: ['IMP-J1', 'IMP-J5'],
    shape: '7 rows, three of them bad',
    provokes:
      'J1.6’s bad-cell branch on both paths, and J5’s row numbering: a bad int, a bad date, a fully blank row (counted in the spreadsheet row numbers the user sees) and `maybe` in a yes/no column.',
  },
)

/* ---- zones-large.csv — chunked sending, and the typed confirmation ---- */
const large = ['Zone Name,Region,Population,Area Sq Km,Opened On,Is Active']
for (let i = 1; i <= 1200; i++) {
  const region = i % 2 ? 'North' : 'South'
  const day = String((i % 28) + 1).padStart(2, '0')
  large.push(
    `Bulk Zone ${String(i).padStart(4, '0')},${region},${1000 + i},${(i % 90) + 0.5},2026-06-${day},${i % 3 ? 'yes' : 'no'}`,
  )
}
csv('zones-large.csv', large, {
  journeys: ['IMP-J2', 'IMP-J5'],
  shape: '1,200 rows',
  provokes:
    'A target sent in more than one part: chunked progress, one Import Log row per part, and a batch that still counts the target once (IMP-I5). Imported twice with a key, it also crosses the typed-confirmation threshold.',
})

/* ---- notes.pdf — J1.2's wrong-file-kind branch ---- */
writeFileSync(join(out, 'notes.pdf'), Buffer.from(minimalPdf('not a spreadsheet')))
manifest.push({
  file: 'notes.pdf',
  journeys: ['IMP-J1'],
  shape: 'one page, no rows at all',
  provokes:
    'J1.2’s wrong-file-kind branch: refused by name — <em>notes.pdf: not a CSV or Excel file</em> — with the screen otherwise unchanged.',
})

