/* ------------------------------------------------------------------ *
 * J4 — three sheets of the same shape, disagreeing only in spelling;
 * one carrying a column the others lack; and a second pair naming the
 * same real-world thing as `Store Code` (STR-009) and `Store Name`
 * (Anna Nagar). Velachery carries BOTH of that pair, which is what
 * makes a first/join rule required rather than optional (IMP-R17).
 * ------------------------------------------------------------------ */
workbook(
  'j4-store-floors.xlsx',
  [
    [
      'Anna Nagar',
      [
        ['Store Code', 'Merge Floor', 'Floor', 'Items', 'Monthly Sales'],
        ['STR-009', 'Ground', 1, 42, 125000],
        ['STR-009', 'Mezzanine', 2, 18, 86000],
        ['STR-009', 'Upper', 3, 12, 41000],
      ],
    ],
    [
      'T Nagar',
      [
        ['Store Name', 'MERGE FLOOR', 'Floor', 'Items', 'Monthly Sales'],
        ['T Nagar', 'Ground', 1, 38, 110500],
        ['T Nagar', 'Mezzanine', 2, 21, 92000],
        ['T Nagar', 'Upper', 3, 30, 54000],
      ],
    ],
    [
      'Velachery',
      [
        ['Store Code', 'Store Name', 'merge_floor ', 'Glor', 'Items', 'Monthly Sales'],
        ['STR-031', 'Velachery', 'Ground', 1, 29, 78000],
        ['STR-031', '', 'Mezzanine', 2, 15, 36500],
        ['STR-031', 'Velachery', 'Upper', 3, 19, 49000],
      ],
    ],
  ],
  {
    journeys: ['IMP-J4', 'IMP-J7'],
    shape: '3 same-shape sheets, 45 cells of disagreement',
    provokes:
      'Every clause of the merge group. <code>Merge Floor</code> · <code>MERGE FLOOR</code> · <code>merge_floor </code> fold into one column (IMP-R16); <code>Glor</code> and <code>Floor</code> do <strong>not</strong> (IMP-H5) and are the pair the user combines; <code>Glor</code> is on one sheet only, so it is also the column the others lack; and <code>Store Code</code> (STR-009) / <code>Store Name</code> (Anna Nagar) are the pair no algorithm could propose — with Velachery carrying both, so a first/join rule is <em>required</em> (IMP-R17). Velachery’s middle row has a blank <code>Store Name</code>, which is what tells <code>first</code> apart from a rule that blanks the row.',
  },
)

