writeFileSync(join(out, 'manifest.json'), JSON.stringify({ fixtures: manifest }, null, 2) + '\n')

console.log(`fixtures written to ${out}`)
for (const f of manifest) console.log(`  ${f.file.padEnd(24)} ${f.journeys.join(' ')}`)

/**
 * A one-page PDF, built byte-exactly so re-running leaves the tree clean.
 * It exists only to be refused by the wizard, so it needs to be a real PDF
 * and nothing more.
 */
function minimalPdf(text) {
  const stream = `BT /F1 14 Tf 40 120 Td (${text}) Tj ET\n`
  const objects = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>',
    `<< /Length ${stream.length} >>\nstream\n${stream}endstream`,
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
  ]
  let pdf = '%PDF-1.4\n'
  const offsets = []
  objects.forEach((body, i) => {
    offsets.push(pdf.length)
    pdf += `${i + 1} 0 obj\n${body}\nendobj\n`
  })
  const xref = pdf.length
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`
  for (const o of offsets) pdf += `${String(o).padStart(10, '0')} 00000 n \n`
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`
  return pdf
}
